// 原人物写回的瞬态捕获组件；不构造业务cause、永久HP账或World资格。
#include "resident/storage/common_codec.hpp"
#include <iostream>
#include <stdexcept>
using namespace hanmo::resident;
namespace {
int checks=0;
// 一处原边界红即停，检查数不是完整玩法完成度。
void need(bool value,const char* text){++checks;if(!value)throw std::runtime_error(text);}
// 只供真实Common writer运行的最小人物/专属资产，不充作Family创建来源。
CommonStore initial(){auto cat=std::make_shared<CommonCatalog>();cat->actor_ids={"p"};CommonState s;s.identity.tick=3;s.identity.revision=8;s.next_instance_id=10;ActorRecord a;a.id="p";a.hp=100;a.fatigue=0;a.location=SettlementLocation{"town","home"};a.wallet_id="wp";a.inventory_id="ip";s.actors.insert(a.id,a);for(const auto& id:{StableId{"p"},StableId{"new"}}){Owner o{Owner::Kind::actor,id,{},{}};s.wallets.insert("w"+id,{"w"+id,o,10,{},{}});s.inventories.insert("i"+id,{"i"+id,o,10,0,{},{}});}return CommonStore(std::move(s),std::move(cat));}
// 同时核原全部序列化值，捕获启用不能改变旧结果或字节。
bool same(const CommonStore& a,const CommonStore& b){return compare_boundary(encode_common_state(a.state()),encode_common_state(b.state())).exact();}
// 动态创建仅借原Common资产门，不伪造任何Family出生因果。
ActorRecord newborn(){ActorRecord a;a.id="new";a.wallet_id="wnew";a.inventory_id="inew";a.hp=100;a.fatigue=0;return a;}
}
int main(){try{
 auto plain=initial(),c=initial();need(c.begin_actor_condition_capture().ok,"begin");auto id=c.actor_condition_capture_identity();need(bool(id),"capture identity");need(!c.begin_actor_condition_capture().ok,"nested capture");need(same(plain,c),"begin changes bytes");
 ActorMutation m;m.actor_id="p";m.hp=100;m.fatigue=0;need(plain.apply_actor(m).ok&&c.apply_actor(m).ok&&same(plain,c),"noop writes changed old bytes");const auto& first=c.actor_condition_execution_drafts().front();need(first.sequence==1&&first.kind==ActorConditionExecutionDraft::Kind::mutation&&first.before&&first.before->hp==100&&first.after.fatigue==0&&first.hp_written&&first.fatigue_written,"same value presence lost");need(first.next_instance_before==10&&first.next_instance_after==10&&first.identity.tick==3,"capture changes ID or clock");
 m={};m.actor_id="p";m.fatigue=11;need(plain.apply_actor(m).ok&&c.apply_actor(m).ok&&same(plain,c),"fatigue actual");const auto& second=c.actor_condition_execution_drafts()[1];need(second.sequence==2&&second.before->fatigue==0&&second.after.fatigue==11&&!second.hp_written&&second.hp_written==m.hp.has_value(),"partial field mask");
 m={};m.actor_id="p";m.location=SettlementLocation{"town","next"};need(plain.apply_actor(m).ok&&c.apply_actor(m).ok&&same(plain,c)&&c.actor_condition_execution_drafts().size()==2,"unrelated mutation captured");
 m.hp=0;m.skills=ActorSkills{};m.skills->martial=1201;auto bad1=plain.apply_actor(m),bad2=c.apply_actor(m);need(!bad1.ok&&!bad2.ok&&bad1.error.original.code==bad2.error.original.code&&same(plain,c)&&c.actor_condition_execution_drafts().size()==2,"failed writer mutated/captured");
 auto fresh=newborn();need(plain.create_actor(fresh,0).ok&&c.create_actor(fresh,0).ok&&same(plain,c),"create changes old bytes");const auto& birth=c.actor_condition_execution_drafts().back();need(birth.sequence==3&&birth.kind==ActorConditionExecutionDraft::Kind::creation&&!birth.before&&birth.after.hp==100&&birth.hp_written&&birth.fatigue_written,"creation is not actual");need(!c.create_actor(fresh,0).ok&&c.actor_condition_execution_drafts().size()==3,"failed create captured");auto got=c.finish_actor_condition_capture();need(got.ok&&got.value.size()==3&&!c.actor_condition_capture_identity(),"finish");need(!c.finish_actor_condition_capture().ok,"double finish");need(c.begin_actor_condition_capture().ok&&c.actor_condition_capture_identity()!=id,"identity reused");need(c.finish_actor_condition_capture().ok,"finish reopened");
 // 原保存点同时撤回人物/资源/读版本和两份捕获，不能只裁一个输出。
 auto rolled=initial(),before=initial();need(rolled.begin_resource_execution_capture().ok&&rolled.begin_actor_condition_capture().ok,"parallel captures");auto aid=rolled.actor_condition_capture_identity();auto point=rolled.begin_savepoint();need(point.ok,"savepoint begin");m={};m.actor_id="p";m.hp=9;m.fatigue=44;need(rolled.apply_actor(m).ok,"savepoint mutation");need(rolled.create_actor(newborn(),0).ok,"savepoint birth");need(rolled.apply_resources({{WalletDelta{"wp",-2,true}}, {}}).ok,"savepoint money");need(!rolled.finish_actor_condition_capture().ok&&!rolled.finish_resource_execution_capture().ok,"savepoint consumed drafts");need(rolled.rollback_savepoint(point.value).ok&&same(rolled,before),"original savepoint rollback changed values");need(rolled.actor_condition_capture_identity()==aid&&rolled.actor_condition_execution_drafts().empty()&&rolled.resource_execution_drafts().empty(),"rollback capture prefix");m.hp=0;m.fatigue.reset();need(rolled.apply_actor(m).ok&&rolled.actor_condition_execution_drafts().back().sequence==1&&rolled.actor_condition_execution_drafts().back().after.hp==0,"rollback sequence or zero lost");need(rolled.finish_actor_condition_capture().ok&&rolled.finish_resource_execution_capture().ok,"finish rollback");
 auto committed=initial();need(committed.begin_actor_condition_capture().ok,"commit begin");auto cp=committed.begin_savepoint();need(cp.ok,"commit savepoint");need(committed.apply_actor(m).ok&&committed.commit_savepoint(cp.value).ok,"commit actual");need(committed.finish_actor_condition_capture().value.size()==1,"committed capture missing");
 // Clone、同址赋值和move不继承捕获；move原保存点撤销人物仍有效。
 auto source=initial();need(source.begin_actor_condition_capture().ok&&source.apply_actor(m).ok,"copy source");CommonStore copied(source);need(same(source,copied)&&!copied.actor_condition_capture_identity()&&copied.actor_condition_execution_drafts().empty(),"copy inherited capture");auto target=initial();need(target.begin_actor_condition_capture().ok,"assignment begin");target=source;need(!target.actor_condition_capture_identity()&&same(target,source),"copy assignment inherited capture");auto sp=source.begin_savepoint();need(sp.ok,"move savepoint");m.hp=70;need(source.apply_actor(m).ok,"move source write");CommonStore moved(std::move(source));need(!source.actor_condition_capture_identity()&&!moved.actor_condition_capture_identity()&&moved.actor_condition_execution_drafts().empty(),"move inherited identity");need(moved.rollback_savepoint(sp.value).ok&&moved.actor("p")->hp==0,"move lost original undo");auto ma=initial();need(ma.begin_actor_condition_capture().ok,"move assign begin");ma=std::move(moved);need(!ma.actor_condition_capture_identity()&&!moved.actor_condition_capture_identity(),"move assignment capture");
 auto raw=initial();need(raw.begin_actor_condition_capture().ok,"limitation begin");raw.state().actors.find("p")->hp=9;need(raw.actor_condition_execution_drafts().empty(),"capture pretends to guard direct state");need(raw.finish_actor_condition_capture().ok,"raw capture no business authority");
 std::cout<<"ACTOR_CONDITION_CAPTURE "<<checks<<"/0 TRANSIENT_COMMON_ONLY\n";return 0;
}catch(const std::exception& e){std::cerr<<"ACTOR_CONDITION_CAPTURE "<<checks<<"/1 "<<e.what()<<'\n';return 1;}}
